#!/usr/bin/env bash
# Convenience runner for the SolidCraft head-to-head driver (isolated experiment).
#   ./run.sh                      corpus mode (all 23 cases; JSON on stdout)
#   ./run.sh --hash               canonical-3 digest line (cross-process determinism)
#   ./run.sh --staircase 200      one staircase scale run (JSON on stdout)
#   ./run.sh --staircase 200 --edit  ... plus the driving-length edit protocol
# The committed envelope is generated by gen_solidcraft_results.py (never by hand).
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BIN="$HERE/target/release/solidcraft-h2h-driver"
if [ ! -x "$BIN" ]; then
  echo "[run.sh] binary missing; run ./build.sh first" >&2
  exit 1
fi
exec "$BIN" "$@"
